  "Take \"{x}\" off {n}": ["إزالة \"{x}\" من {n} مجموعة", "إزالة \"{x}\" من مجموعة واحدة ({n})", "إزالة \"{x}\" من مجموعتين ({n})", "إزالة \"{x}\" من {n} مجموعات", "إزالة \"{x}\" من {n} مجموعة", "إزالة \"{x}\" من {n} مجموعة"],
